package main

import ("fmt";"encoding/xml";"io";"os";"strings")

func main(){
  data,_ := io.ReadAll(os.Stdin)
  strict := len(os.Args)>1 && os.Args[1]=="strict"
  d := xml.NewDecoder(strings.NewReader(string(data)))
  d.Strict = strict
  for {
    tok, err := d.Token()
    if err != nil { fmt.Println("ERR:", err); break }
    switch t := tok.(type) {
    case xml.Directive: fmt.Printf("DIR %q\n", string(t))
    case xml.ProcInst: fmt.Printf("PI %q %q\n", t.Target, t.Inst)
    case xml.StartElement: fmt.Printf("START %q (space=%q) attrs=%v\n", t.Name.Local, t.Name.Space, t.Attr)
    case xml.EndElement: fmt.Printf("END %q (space=%q)\n", t.Name.Local, t.Name.Space)
    case xml.CharData: fmt.Printf("TEXT %q\n", string(t))
    case xml.Comment: fmt.Printf("CMT %q\n", string(t))
    }
  }
}
EOF
