package internal

// Token kinds produced by the tokenizer.
const (
	tkText = iota
	tkStart
	tkEnd
	tkComment
	tkPI
	tkDirective
	tkCDATA
)

// Attr is a single tag attribute.
type Attr struct {
	Name  string
	Value string
}

// Token is a single lexical token of the input document.
type Token struct {
	Kind        int
	Name        string
	Attrs       []Attr
	Text        string
	SelfClosing bool
	Line        int
}

// Tokenizer walks the input and yields tokens.
type Tokenizer struct {
	data []byte
	pos  int
	line int
	html bool
}

// NewTokenizer returns a tokenizer for the given input.
func NewTokenizer(data []byte, html bool) *Tokenizer {
	return &Tokenizer{data: data, html: html}
}

func isSpace(c byte) bool {
	return c == ' ' || c == '\t' || c == '\n' || c == '\r'
}

func isNameStart(c byte) bool {
	return c == '_' || (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || c > 127
}

func isNameChar(c byte) bool {
	return isNameStart(c) || (c >= '0' && c <= '9') || c == '-' || c == '.' || c == ':' || c == '"' || c == '\''
}

// Next returns the next token, or nil at end of input.
func (t *Tokenizer) Next() *Token {
	for t.pos < len(t.data) {
		if t.data[t.pos] != '<' {
			start := t.pos
			for t.pos < len(t.data) && t.data[t.pos] != '<' {
				if t.data[t.pos] == '\n' {
					t.line++
				}
				t.pos++
			}
			return &Token{Kind: tkText, Text: decodeEntities(string(t.data[start:t.pos]), t.html), Line: t.line}
		}
		// markup
		if t.pos+3 < len(t.data) && t.data[t.pos+1] == '!' && t.data[t.pos+2] == '-' && t.data[t.pos+3] == '-' {
			return t.comment()
		}
		if t.pos+1 < len(t.data) && t.data[t.pos+1] == '?' {
			return t.procInst()
		}
		if t.pos+8 < len(t.data) && t.data[t.pos+1] == '!' && string(t.data[t.pos+2:t.pos+9]) == "[CDATA[" {
			return t.cdata()
		}
		if t.pos+1 < len(t.data) && t.data[t.pos+1] == '!' {
			return t.directive()
		}
		if t.pos+1 < len(t.data) && t.data[t.pos+1] == '/' {
			return t.endTag()
		}
		if t.pos+1 >= len(t.data) || !isNameStart(t.data[t.pos+1]) {
			// treat as text
			start := t.pos
			t.pos++
			return &Token{Kind: tkText, Text: string(t.data[start:t.pos]), Line: t.line}
		}
		return t.startTag()
	}
	return nil
}

func (t *Tokenizer) comment() *Token {
	start := t.pos + 4
	i := start
	for i+2 <= len(t.data) {
		if t.data[i] == '-' && t.data[i+1] == '-' && i+2 < len(t.data) && t.data[i+2] == '>' {
			t.pos = i + 3
			return &Token{Kind: tkComment, Text: string(t.data[start:i]), Line: t.line}
		}
		if t.data[i] == '\n' {
			t.line++
		}
		i++
	}
	t.pos = len(t.data)
	return &Token{Kind: tkComment, Text: string(t.data[start:]), Line: t.line}
}

func (t *Tokenizer) cdata() *Token {
	start := t.pos + 9
	i := start
	for i+2 < len(t.data) {
		if t.data[i] == ']' && t.data[i+1] == ']' && t.data[i+2] == '>' {
			t.pos = i + 3
			return &Token{Kind: tkCDATA, Text: string(t.data[start:i]), Line: t.line}
		}
		if t.data[i] == '\n' {
			t.line++
		}
		i++
	}
	t.pos = len(t.data)
	return &Token{Kind: tkCDATA, Text: string(t.data[start:]), Line: t.line}
}

func (t *Tokenizer) procInst() *Token {
	start := t.pos + 2
	i := start
	for i+1 < len(t.data) {
		if t.data[i] == '?' && t.data[i+1] == '>' {
			t.pos = i + 2
			return &Token{Kind: tkPI, Text: string(t.data[start:i]), Line: t.line}
		}
		if t.data[i] == '\n' {
			t.line++
		}
		i++
	}
	t.pos = len(t.data)
	return &Token{Kind: tkPI, Text: string(t.data[start:]), Line: t.line}
}

func (t *Tokenizer) directive() *Token {
	start := t.pos + 2
	i := start
	for i < len(t.data) {
		if t.data[i] == '>' {
			t.pos = i + 1
			return &Token{Kind: tkDirective, Text: string(t.data[start:i]), Line: t.line}
		}
		if t.data[i] == '\n' {
			t.line++
		}
		i++
	}
	t.pos = len(t.data)
	return &Token{Kind: tkDirective, Text: string(t.data[start:]), Line: t.line}
}

func (t *Tokenizer) endTag() *Token {
	start := t.pos + 2
	i := start
	for i < len(t.data) && !isSpace(t.data[i]) && t.data[i] != '>' {
		i++
	}
	name := string(t.data[start:i])
	for i < len(t.data) && isSpace(t.data[i]) {
		i++
	}
	if i < len(t.data) && t.data[i] == '>' {
		i++
	}
	t.pos = i
	return &Token{Kind: tkEnd, Name: t.normName(name), Line: t.line}
}

func (t *Tokenizer) normName(n string) string {
	if t.html {
		n = strings.ToLower(n)
	}
	return n
}

func (t *Tokenizer) startTag() *Token {
	start := t.pos + 1
	i := start
	for i < len(t.data) && !isSpace(t.data[i]) && t.data[i] != '>' && t.data[i] != '/' {
		i++
	}
	name := string(t.data[start:i])
	tok := &Token{Kind: tkStart, Name: t.normName(name), Line: t.line}
	for {
		for i < len(t.data) && isSpace(t.data[i]) {
			i++
		}
		if i >= len(t.data) {
			break
		}
		if t.data[i] == '>' {
			i++
			break
		}
		if t.data[i] == '/' {
			if i+1 < len(t.data) && t.data[i+1] == '>' {
				tok.SelfClosing = true
				i += 2
				break
			}
			i++
			continue
		}
		// attribute name
		j := i
		for j < len(t.data) && !isSpace(t.data[j]) && t.data[j] != '>' && t.data[j] != '/' && t.data[j] != '=' {
			j++
		}
		aname := string(t.data[i:j])
		if t.html {
			aname = strings.ToLower(aname)
		}
		i = j
		for i < len(t.data) && isSpace(t.data[i]) {
			i++
		}
		value := aname
		if i < len(t.data) && t.data[i] == '=' {
			i++
			for i < len(t.data) && isSpace(t.data[i]) {
				i++
			}
			if i < len(t.data) && (t.data[i] == '"' || t.data[i] == '\'') {
				q := t.data[i]
				i++
				vs := i
				for i < len(t.data) && t.data[i] != q {
					i++
				}
				value = decodeEntities(string(t.data[vs:i]), t.html)
				if i < len(t.data) {
					i++
				}
			} else {
				vs := i
				for i < len(t.data) && !isSpace(t.data[i]) && t.data[i] != '>' {
					i++
				}
				value = decodeEntities(string(t.data[vs:i]), t.html)
			}
		}
		tok.Attrs = append(tok.Attrs, Attr{Name: aname, Value: value})
	}
	t.pos = i
	return tok
}
