func xmlUnescape(s string) string {
	if !strings.ContainsRune(s, '&') {
		return s
	}
	var sb strings.Builder
	sb.Grow(len(s))
	i := 0
	for i < len(s) {
		if s[i] != '&' {
			sb.WriteByte(s[i])
			i++
			continue
		}
		j := i + 1
		for j < len(s) && s[j] != ';' {
			j++
		}
		if j >= len(s) || j == i+1 || j-i > 12 {
			sb.WriteByte(s[i])
			i++
			continue
		}
		name := s[i+1 : j]
		if name[0] == '#' {
			var code rune
			var ok bool
			if len(name) > 2 && (name[1] == 'x' || name[1] == 'X') {
				code, ok = parseUintRune(name[2:], 16)
			} else {
				code, ok = parseUintRune(name[1:], 10)
			}
			if !ok || isXMLIllegal(code) {
				sb.WriteString(s[i : j+1])
			} else {
				sb.WriteRune(code)
			}
		} else if rep, found := xmlEntities[name]; found {
			sb.WriteString(rep)
		} else {
			sb.WriteString(s[i : j+1])
		}
		i = j + 1
	}
	return sb.String()
}

func parseUintRune(s string, base int) (rune, bool) {
	if s == "" {
		return 0, false
	}
	var v uint64
	for _, c := range s {
		var d uint64
		switch {
		case c >= '0' && c <= '9':
			d = uint64(c - '0')
		case base == 16 && c >= 'a' && c <= 'f':
			d = uint64(c-'a') + 10
		case base == 16 && c >= 'A' && c <= 'F':
			d = uint64(c-'A') + 10
		default:
			return 0, false
		}
		v = v*uint64(base) + d
		if v > 0x10FFFF {
			return 0, false
		}
	}
	return rune(v), true
}
