{"command": "cd /workspace && cat > internal/tree.go <<'GOEOF'
package internal

import (
	"strings"
)

// Document is the root of the parsed document tree.
type Document struct {
	Kids   []*Node
	HTML   bool
	Indent string
}

// Parser builds a document tree out of the token stream.
type Parser struct {
	tok    *Tokenizer
	doc    *Document
	stack  []*Node
	html   bool
	errMsg string
}

// Parse parses the input into a document tree.
func Parse(data []byte, html bool) (*Document, error) {
	p := &Parser{tok: NewTokenizer(data, html), html: html}
	p.doc = &Document{HTML: html}
	for {
		t := p.tok.Next()
		if t == nil {
			break
		}
		switch t.Kind {
		case tkText:
			p.addChild(&Node{Kind: ndText, Text: t.Text, Line: t.Line})
		case tkCDATA:
			p.addChild(&Node{Kind: ndCDATA, Text: t.Text, Line: t.Line})
		case tkComment:
			p.addChild(&Node{Kind: ndComment, Text: t.Text, Line: t.Line})
		case tkDirective:
			p.addChild(&Node{Kind: ndDirective, Text: t.Text, Line: t.Line})
		case tkPI:
			p.addChild(&Node{Kind: ndPI, Text: t.Text, Line: t.Line})
		case tkStart:
			n := &Node{Kind: ndElement, Name: t.Name, Attrs: t.Attrs, Line: t.Line}
			if t.SelfClosing {
				n.Void = true
				p.addChild(n)
			} else if html && voidElements[t.Name] {
				n.Void = true
				p.addChild(n)
			} else {
				p.addChild(n)
				p.stack = append(p.stack, n)
			}
		case tkEnd:
			var popped *Node
			if len(p.stack) > 0 {
				popped = p.stack[len(p.stack)-1]
				p.stack = p.stack[:len(p.stack)-1]
			}
			if popped != nil {
				if t.Name != popped.Name && html {
					// keep the original end tag name for rendering
					popped.EndName = t.Name
				}
				if !html && t.Name != popped.Name {
					// xml mode: unexpected end element
					return nil, &XMLSyntaxError{Line: t.Line, Msg: "XML syntax error on line " + itoa(t.Line) + ": unexpected end element </" + t.Name + ">"}
				}
			}
		}
	}
	return p.doc, nil
}

func itoa(i int) string {
	return strings.Repeat("", 0) + strconvItoa(i)
}
GOEOF
echo ok"}

