{"command": "cd /workspace && cat > internal/tree.go <<'GOEOF'
package internal

// Parser builds a document tree out of the token stream.
type Parser struct {
	tok   *Tokenizer
	doc   *Document
	stack []*Node
	html  bool
	err   error
}

// Parse parses the input into a document tree.
func Parse(data []byte, html bool) (*Document, error) {
	p := &Parser{tok: NewTokenizer(data, html), html: html}
	p.doc = &Document{HTML: html}
	for p.err == nil {
		t := p.tok.Next()
		if t == nil {
			break
		}
		switch t.Kind {
		case tkText:
			p.addChild(&Node{Kind: ndText, Text: t.Text, Line: t.Line})
		case tkCDATA:
			p.addChild(&Node{Kind: ndCDATA, Text: t.Text, Line: t.Line})
		case tkComment:
			p.addChild(&Node{Kind: ndComment, Text: t.Text, Line: t.Line})
		case tkDirective:
			p.addChild(&Node{Kind: ndDirective, Text: t.Text, Line: t.Line})
		case tkPI:
			p.addChild(&Node{Kind: ndPI, Text: t.Text, Line: t.Line})
		case tkStart:
			n := &Node{Kind: ndElement, Name: t.Name, Attrs: t.Attrs, Line: t.Line}
			if t.SelfClosing {
				n.Void = true
				p.addChild(n)
			} else if html && voidElements[t.Name] {
				n.Void = true
				p.addChild(n)
			} else {
				p.addChild(n)
				p.stack = append(p.stack, n)
			}
		case tkEnd:
			idx := -1
			for i := len(p.stack) - 1; i >= 0; i-- {
				if p.stack[i].Name == t.Name {
					idx = i
					break
				}
			}
			if idx >= 0 {
				for len(p.stack) > idx+1 {
					p.stack[len(p.stack)-1].Void = true
					p.stack = p.stack[:len(p.stack)-1]
				}
				top := p.stack[len(p.stack)-1]
				if p.html {
					top.EndName = t.Name
				}
				p.stack = p.stack[:len(p.stack)-1]
			} else if len(p.stack) > 0 {
				if !p.html {
					p.err = &XMLSyntaxError{Line: t.Line, Msg: "XML syntax error on line " + utoa(t.Line) + ": unexpected end element </" + t.Name + ">"}
					for len(p.stack) > 0 {
						p.stack[len(p.stack)-1].Void = true
						p.stack = p.stack[:len(p.stack)-1]
					}
				} else {
					for len(p.stack) > 0 {
						p.stack = p.stack[:len(p.stack)-1]
					}
				}
			} else if !p.html {
				p.err = &XMLSyntaxError{Line: t.Line, Msg: "XML syntax error on line " + utoa(t.Line) + ": unexpected end element </" + t.Name + ">"}
			}
		}
	}
	return p.doc, p.err
}

func (p *Parser) addChild(n *Node) {
	if len(p.stack) > 0 {
		top := p.stack[len(p.stack)-1]
		n.Parent = top
		top.Kids = append(top.Kids, n)
	} else {
		n.Parent = nil
		p.doc.Kids = append(p.doc.Kids, n)
	}
}

func utoa(i int) string {
	if i == 0 {
		return "0"
	}
	var b [8]byte
	n := len(b)
	for i > 0 {
		n--
		b[n] = byte('0' + i%10)
		i /= 10
	}
	return string(b[n:])
}
GOEOF
