{"command": "cd /workspace && cat > internal/format.go <<'GOEOF'
package internal

import (
	"strings"
)

// Options controls the formatting.
type Options struct {
	IndentUnit string
	Color      bool
	HTML       bool
	Depth      int
}

var voidElements = map[string]bool{
	"area": true, "base": true, "br": true, "col": true, "embed": true,
	"hr": true, "img": true, "input": true, "keygen": true, "link": true,
	"meta": true, "param": true, "source": true, "track": true, "wbr": true,
}

// Format renders the document.
func Format(doc *Document, opts *Options) string {
	var b strings.Builder
	f := &formatter{opts: opts}
	f.b = &b
	for _, n := range doc.Kids {
		f.topNode(n, 0)
	}
	b.WriteString("\n")
	return b.String()
}

type formatter struct {
	b    *strings.Builder
	opts *Options
}

func (f *formatter) write(s string) {
	f.b.WriteString(s)
}

func (f *formatter) ind(depth int) string {
	if depth < 0 {
		depth = 0
	}
	return strings.Repeat(f.opts.IndentUnit, depth)
}

func (f *formatter) nl(depth int) {
	f.b.WriteString("\n" + f.ind(depth))
}

func (f *formatter) topNode(n *Node, depth int) {
	switch n.Kind {
	case ndText:
		f.text(n, depth)
	case ndComment:
		f.comment(n)
		f.write("\n")
	case ndPI:
		f.pi(n)
		f.write("\n")
	case ndDirective:
		f.directive(n)
		f.write("\n")
	case ndElement:
		f.element(n, depth, true)
	}
}

func (f *formatter) text(n *Node, depth int) {
	s := n.Text
	if strings.TrimSpace(s) == "" {
		return
	}
	if f.opts.HTML {
		f.write(strings.TrimRight(s, " "))
		return
	}
	if len(s) > 0 {
		// leading whitespace collapse: spaces*, newline, spaces+
		if m := reLead.FindStringIndex(s); m != nil {
			s = "\n" + f.ind(depth) + s[m[1]:]
		}
	}
	// CDATA when escaping is required
	if strings.ContainsAny(s, "&<") {
		s = "<![CDATA[" + s + "]]>"
	}
	f.write(s)
}

func (f *formatter) cdata(n *Node, depth int) {
	f.write(n.Text)
}

func (f *formatter) comment(n *Node) {
	if f.opts.Color {
		f.write("\x1b[94m<!--\x1b[0m\x1b[94m" + n.Text + "\x1b[0m\x1b[94m-->\x1b[0m")
	} else {
		f.write("<!--" + n.Text + "-->")
	}
}

func (f *formatter) pi(n *Node) {
	txt := n.Text
	i := strings.IndexByte(txt, ' ')
	var target, inst string
	if i < 0 {
		target = txt
	} else {
		target, inst = txt[:i], txt[i+1:]
	}
	f.write("<?" + target)
	if inst != "" {
		for _, kv := range strings.Split(inst, " ") {
			if kv == "" {
				continue
			}
			parts := strings.Split(kv, "=")
			f.write(" " + parts[0])
			if len(parts) > 1 {
				v := strings.Trim(parts[1], "\"'")
				if f.opts.Color {
					f.write("\x1b[32m=\"" + v + "\"\x1b[0m")
				} else {
					f.write("=\"" + v + "\"")
				}
			}
		}
	}
	f.write("?>")
}

func (f *formatter) directive(n *Node) {
	txt := n.Text
	if i := strings.IndexByte(txt, ' '); i > 0 {
		f.write("<!" + strings.ToLower(txt[:i]) + " " + txt[i+1:] + ">")
	} else {
		f.write("<!" + strings.ToLower(txt) + ">")
	}
}

func (f *formatter) startTag(n *Node) {
	f.write("<" + n.Name)
	for _, a := range n.Attrs {
		f.write(" " + a.Name)
		if f.opts.HTML {
			if f.opts.Color {
				f.write("\x1b[32m=\"" + htmlEscape(a.Value) + "\"\x1b[0m")
			} else {
				f.write("=\"" + htmlEscape(a.Value) + "\"")
			}
		} else {
			if f.opts.Color {
				f.write("\x1b[32m=\"" + xmlEscape(a.Value) + "\"\x1b[0m")
			} else {
				f.write("=\"" + xmlEscape(a.Value) + "\"")
			}
		}
	}
}

func (f *formatter) hasContent(n *Node) bool {
	for _, c := range n.Kids {
		switch c.Kind {
		case ndText:
			if strings.TrimSpace(c.Text) != "" {
				return true
			}
		case ndCDATA:
			if strings.TrimSpace(c.Text) != "" {
				return true
			}
		case ndElement:
			return true
		}
	}
	return false
}

// element renders an element node. sep tells whether a line separator precedes it.
func (f *formatter) element(n *Node, depth int, sep bool) {
	if sep {
		f.nl(depth)
	}
	f.startTag(n)
	if n.Void {
		if f.opts.HTML || len(n.Kids) == 0 {
			f.write("/>")
			f.children(n, depth)
			return
		}
		f.write(">")
		f.children(n, depth)
		f.write("/>")
		return
	}
	if len(n.Kids) == 0 {
		if f.opts.HTML {
			f.write("></" + n.Name + ">")
		} else {
			f.write("/>")
		}
		return
	}
	f.write(">")
	lastBlock := f.children(n, depth)
	if f.opts.HTML {
		if f.hasNonVoidChild(n) {
			f.nl(depth)
