package internal

import (
	"strconv"
	"strings"
)

// jsonVal is a minimal JSON value.
type jsonVal struct {
	kind   int // 0 obj, 1 arr, 2 str, 3 num, 4 bool, 5 null
	keys   []string
	vals   []*jsonVal
	str    string
	raw    string
	b      bool
}

func (v *jsonVal) strKey() string { return v.str }

// jsonTree converts an element into a json value.
func jsonTree(n *Node, depth, limit int) *jsonVal {
	o := &jsonVal{kind: 0}
	texts := []string{}
	for _, c := range n.Kids {
		switch c.Kind {
		case ndText:
			t := strings.TrimSpace(c.Text)
			if t != "" {
				texts = append(texts, t)
			}
		case ndCDATA:
			t := strings.TrimSpace(c.Text)
			if t != "" {
				texts = append(texts, t)
			}
		}
	}
	if depth < limit || limit < 0 {
		for _, c := range n.Kids {
			if c.Kind != ndElement {
				continue
			}
			o.keys = append(o.keys, c.Name)
			o.vals = append(o.vals, jsonTree(c, depth+1, limit))
		}
	} else {
		for _, c := range n.Kids {
			if c.Kind != ndElement {
				continue
			}
			o.keys = append(o.keys, c.Name)
			o.vals = append(o.vals, subText(c))
		}
	}
	for _, a := range n.Attrs {
		o.keys = append(o.keys, "@"+a.Name)
		o.vals = append(o.vals, &jsonVal{kind: 2, str: a.Value})
	}
	if len(texts) > 0 {
		if len(o.keys) == 0 && len(texts) == 1 {
			return &jsonVal{kind: 2, str: texts[0]}
		}
		o.keys = append(o.keys, "#text")
		o.vals = append(o.vals, &jsonVal{kind: 2, str: strings.Join(texts, "\n")})
	}
	return o
}

func subText(n *Node) *jsonVal {
	texts := []string{}
	var walk func(x *Node)
	walk = func(x *Node) {
		for _, c := range x.Kids {
			switch c.Kind {
			case ndText:
				t := strings.TrimSpace(c.Text)
				if t != "" {
					texts = append(texts, t)
				}
			case ndCDATA:
				t := strings.TrimSpace(c.Text)
				if t != "" {
					texts = append(texts, t)
				}
			case ndElement:
				walk(c)
			}
		}
	}
	walk(n)
	return &jsonVal{kind: 2, str: strings.Join(texts, "\n")}
}

// sortJSON sorts the keys of every object.
func sortJSON(v *jsonVal) {
	if v == nil || v.kind != 0 {
		return
	}
	for i := 0; i < len(v.keys); i++ {
		for j := i + 1; j < len(v.keys); j++ {
			if v.keys[j] < v.keys[i] {
				v.keys[i], v.keys[j] = v.keys[j], v.keys[i]
				v.vals[i], v.vals[j] = v.vals[j], v.vals[i]
			}
		}
	}
	// merge duplicates into arrays
	var nk []string
	var nv []*jsonVal
	for i := 0; i < len(v.keys); i++ {
		if i+1 < len(v.keys) && v.keys[i+1] == v.keys[i] {
			continue
		}
		if i > 0 && v.keys[i-1] == v.keys[i] {
			// gather duplicates
			start := i
			for start > 0 && v.keys[start-1] == v.keys[i] {
				start--
			}
			arr := &jsonVal{kind: 1}
			for k := start; k <= i; k++ {
				arr.vals = append(arr.vals, v.vals[k])
			}
			nk = append(nk, v.keys[i])
			nv = append(nv, arr)
			continue
		}
		nk = append(nk, v.keys[i])
		nv = append(nv, v.vals[i])
	}
	v.keys, v.vals = nk, nv
	for _, c := range v.vals {
		sortJSON(c)
	}
}

func writeJSON(v *jsonVal, indent string, compact bool, sb *strings.Builder) {
	switch v.kind {
	case 0:
		if len(v.keys) == 0 {
			if compact {
				sb.WriteString("{}")
			} else {
				sb.WriteString("{\n\n" + indent + "}")
			}
			return
		}
		sb.WriteString("{")
		for i, k := range v.keys {
			if compact {
				if i > 0 {
					sb.WriteString(",")
				}
			} else {
				sb.WriteString("\n" + indent + "  ")
			}
			sb.WriteString(strconvQuote(k) + ": ")
			writeJSON(v.vals[i], indent+"  ", compact, sb)
			if !compact {
