package internal

import (
	"strings"
)

// cssMatch returns the elements matching the css selector, in document order.
func cssMatch(doc *Document, sel string) []*Node {
	var all []*Node
	var walk func(n *Node)
	walk = func(n *Node) {
		if n.Kind == ndElement {
			all = append(all, n)
		}
		for _, c := range n.Kids {
			walk(c)
		}
	}
	for _, k := range doc.Kids {
		walk(k)
	}
	toks := splitCss(sel)
	if len(toks) == 0 {
		return nil
	}
	var res []*Node
	for _, n := range all {
		if matchCompound(n, toks[len(toks)-1]) {
			if len(toks) == 1 {
				res = append(res, n)
				continue
			}
			if matchAncestors(n, toks[:len(toks)-1]) {
				res = append(res, n)
			}
		}
	}
	return res
}

// splitCss splits the selector into compound selectors.
func splitCss(sel string) []string {
	var out []string
	cur := ""
	depth := 0
	for i := 0; i < len(sel); i++ {
		c := sel[i]
		if c == '[' {
			depth++
		}
		if c == ']' {
			depth--
		}
		if depth == 0 && c == '>' {
			if strings.TrimSpace(cur) != "" {
				out = append(out, strings.TrimSpace(cur))
			}
			cur = ">"
			continue
		}
		if depth == 0 && c == ' ' {
			if cur == ">" || cur == "" {
				continue
			}
			out = append(out, strings.TrimSpace(cur))
			cur = ""
			continue
		}
		cur += string(c)
	}
	if strings.TrimSpace(cur) != "" {
		out = append(out, strings.TrimSpace(cur))
	}
	return out
}

func matchAncestors(n *Node, toks []string) bool {
	i := len(toks) - 1
	cur := n.Parent
	child := n
	for i >= 0 {
		if toks[i] == ">" {
			i--
			continue
		}
		if cur == nil || cur.Kind != ndElement {
			return false
		}
		if !matchCompound(cur, toks[i]) {
			return false
		}
		if i > 0 && toks[i-1] == ">" {
			// child combinator: parent must be the direct parent (already is)
			_ = child
			i--
			continue
		}
		child = cur
		cur = cur.Parent
		i--
	}
	return true
}

func matchCompound(n *Node, c string) bool {
	i := 0
	// tag name
	for i < len(c) && c[i] != '.' && c[i] != '#' && c[i] != '[' {
		i++
	}
	name := c[:i]
	if name != "" && name != "*" && name != n.Name {
		return false
	}
	for i < len(c) {
		switch c[i] {
		case '.':
			j := i + 1
			for j < len(c) && c[j] != '.' && c[j] != '#' && c[j] != '[' {
				j++
			}
			cls := c[i+1 : j]
			found := false
			for _, a := range n.Attrs {
				if a.Name == "class" {
					for _, p := range strings.Fields(a.Value) {
						if p == cls {
							found = true
						}
					}
				}
			}
			if !found {
				return false
			}
			i = j
		case '#':
			j := i + 1
			for j < len(c) && c[j] != '.' && c[j] != '#' && c[j] != '[' {
				j++
			}
			id := c[i+1 : j]
			found := false
			for _, a := range n.Attrs {
				if a.Name == "id" && a.Value == id {
					found = true
				}
			}
			if !found {
				return false
			}
			i = j
		case '[':
			j := strings.IndexByte(c[i:], ']')
			if j < 0 {
				return false
			}
			expr := c[i+1 : i+j]
			if !matchAttr(n, expr) {
				return false
			}
			i += j + 1
		default:
			i++
		}
	}
	return true
}

func matchAttr(n *Node, expr string) bool {
	var name, op, val string
	for i := 0; i < len(expr); i++ {
		if expr[i] == '=' || expr[i] == '~' || expr[i] == '^' || expr[i] == '$' || expr[i] == '*' || expr[i] == '|' {
			name = strings.TrimSpace(expr[:i])
			if expr[i] != '=' {
				op = string(expr[i])
				i++
			}
			val = strings.TrimSpace(expr[i+1:])
			val = strings.Trim(val, "\"'")
			break
		}
	}
	if name == "" {
		return false
	}
	var actual string
	found := false
	for _, a := range n.Attrs {
		if a.Name == name {
			actual = a.Value
			found = true
		}
	}
	if op == "" {
		return found
	}
	if !found {
		return false
	}
	switch op {
	case "^":
		return strings.HasPrefix(actual, val)
	case "$":
		return strings.HasSuffix(actual, val)
	case "*":
		return strings.Contains(actual, val)
	case "~":
		for _, p := range strings.Fields(actual) {
			if p == val {
				return true
			}
		}
		return false
	default:
		return actual == val
	}
}
