		case '#':
			j := i + 1
			for j < len(c) && c[j] != '.' && c[j] != '#' && c[j] != '[' {
				j++
			}
			id := c[i+1 : j]
			found := false
			for _, a := range n.Attrs {
				if a.Name == "id" && a.Value == id {
					found = true
				}
			}
			if !found {
				return false
			}
			i = j
		case '[':
			j := strings.IndexByte(c[i:], ']')
			if j < 0 {
				return false
			}
			expr := c[i+1 : i+j]
			if !matchAttr(n, expr) {
				return false
			}
			i += j + 1
		default:
			i++
		}
	}
	return true
}

func matchAttr(n *Node, expr string) bool {
	var name, op, val string
	for i := 0; i < len(expr); i++ {
		if expr[i] == '=' || expr[i] == '~' || expr[i] == '^' || expr[i] == '$' || expr[i] == '*' || expr[i] == '|' {
			name = strings.TrimSpace(expr[:i])
			if expr[i] != '=' {
				op = string(expr[i])
				i++
			}
			val = strings.TrimSpace(expr[i+1:])
			val = strings.Trim(val, "\"'")
			break
		}
	}
	if name == "" {
		return false
	}
	var actual string
	found := false
	for _, a := range n.Attrs {
		if a.Name == name {
			actual = a.Value
			found = true
		}
	}
	if op == "" {
		return found
	}
	if !found {
		return false
	}
	switch op {
	case "^":
		return strings.HasPrefix(actual, val)
	case "$":
		return strings.HasSuffix(actual, val)
	case "*":
		return strings.Contains(actual, val)
	case "~":
		for _, p := range strings.Fields(actual) {
			if p == val {
				return true
			}
		}
		return false
	default:
		return actual == val
	}
}
