package internal

import (
	"strconv"
	"strings"
)

// xpathMatch evaluates a subset of XPath and returns matching nodes (or nil).
func xpathMatch(doc *Document, q string) ([]*Node, error) {
	alts := strings.Split(q, "|")
	var res []*Node
	for _, alt := range alts {
		ns, err := xpathOne(doc, strings.TrimSpace(alt))
		if err != nil {
			return nil, err
		}
		res = append(res, ns...)
	}
	return res, nil
}

func allElems(doc *Document) []*Node {
	var all []*Node
	var walk func(n *Node)
	walk = func(n *Node) {
		if n.Kind == ndElement {
			all = append(all, n)
		}
		for _, c := range n.Kids {
			walk(c)
		}
	}
	for _, k := range doc.Kids {
		walk(k)
	}
	return all
}

func xpathOne(doc *Document, q string) ([]*Node, error) {
	// absolute path from document root
	if strings.HasPrefix(q, "/") && !strings.HasPrefix(q, "//") {
		q = q[1:]
	}
	q = strings.TrimPrefix(q, ".")
	parts := strings.Split(q, "/")
	var cur []*Node
	var curRoots []*Node
	for _, k := range doc.Kids {
		curRoots = append(curRoots, k)
	}
	if strings.HasPrefix(q, "/") {
		for _, k := range doc.Kids {
			cur = append(cur, k)
		}
		q = strings.TrimPrefix(q, "/")
		if q == "" {
			return cur, nil
		}
		parts = strings.Split(q, "/")
	}
	// build a list of "context" nodes: element nodes under each root
	cur = nil
	var walk func(n *Node)
	walk = func(n *Node) {
		if n.Kind == ndElement {
			cur = append(cur, n)
		}
		for _, c := range n.Kids {
			walk(c)
		}
	}
	for _, k := range doc.Kids {
		walk(k)
	}
	segments := strings.Split(strings.TrimLeft(q, "/"), "/")
	descendant := false
	for _, seg := range segments {
		if seg == "//" {
			descendant = true
			continue
		}
		if seg == "" {
			descendant = true
			continue
		}
		name := seg
		pred := ""
		if i := strings.IndexByte(seg, '['); i >= 0 {
			name = seg[:i]
			pred = strings.TrimSuffix(seg[i+1:], "]")
		}
		var next []*Node
		for _, n := range cur {
			if descendant {
				var rec func(x *Node)
				rec = func(x *Node) {
					for _, c := range x.Kids {
						if c.Kind == ndElement {
							next = append(next, c)
							rec(c)
						}
					}
				}
				rec(n)
				continue
			}
			for _, c := range n.Kids {
				if c.Kind == ndElement && (name == "*" || c.Name == name) {
					next = append(next, c)
				}
			}
		}
		descendant = false
		if pred != "" {
			var filtered []*Node
			for _, n := range next {
				if predMatch(n, pred) {
					filtered = append(filtered, n)
				}
			}
			next = filtered
		}
		cur = next
	}
	return cur, nil
}

func predMatch(n *Node, pred string) bool {
	if pred == "" {
		return true
	}
	// numeric index (1-based)
	if v, err := strconv.Atoi(pred); err == nil {
		idx := 1
		for _, s := range n.Parent.Kids {
			if s.Kind == ndElement && s.Name == n.Name {
				if s == n {
					return idx == v
				}
				idx++
			}
		}
		return false
	}
	// [attr="val"] or [@attr="val"]
	pred = strings.TrimPrefix(pred, "@")
	if i := strings.Index(pred, "="); i >= 0 {
		aname := strings.TrimSpace(pred[:i])
		aval := strings.TrimSpace(pred[i+1:])
		aval = strings.Trim(aval, "\"'")
		for _, a := range n.Attrs {
			if a.Name == aname && a.Value == aval {
				return true
			}
		}
		return false
	}
	if pred == "last()" {
		cnt := 0
		for _, s := range n.Parent.Kids {
			if s.Kind == ndElement && s.Name == n.Name {
				cnt++
			}
		}
		// position equals count
		idx := 0
		for _, s := range n.Parent.Kids {
			if s.Kind == ndElement && s.Name == n.Name {
				idx++
				if s == n {
					return idx == cnt
				}
			}
		}
		return false
	}
	return true
}

// textContent returns the concatenated text of a subtree.
func textContent(n *Node) string {
	var sb strings.Builder
	var walk func(x *Node)
	walk = func(x *Node) {
		for _, c := range x.Kids {
			switch c.Kind {
			case ndText:
				sb.WriteString(c.Text)
			case ndCDATA:
				sb.WriteString(c.Text)
			case ndElement:
				walk(c)
			}
		}
	}
	walk(n)
	return sb.String()
}
