package main

import (
	"encoding/json"
	"fmt"
	"io"
	"os"
	"strings"

	"xq/internal"
)

const version = "xq version 1.4.0"

const helpText = `Command-line XML and HTML beautifier and content extractor

Usage:
  xq [flags]

Flags:
  -a, --attr string      Extract an attribute value instead of node content for provided CSS query
  -c, --color            Force colorful output
      --compact          Compact JSON output (no indentation)
  -d, --depth int        Maximum nesting depth for JSON output (-1 for unlimited) (default -1)
  -e, --extract string   Extract a single node from XML
  -h, --help             Print this help message
  -m, --html             Use HTML formatter
  -i, --in-place         Format file in place
      --indent int       Use the given number of spaces for indentation (default 2)
  -j, --json             Output the result as JSON
      --no-color         Disable colorful output
  -n, --node             Return the node content instead of text
  -q, --query string     Extract the node(s) using CSS selector
      --tab              Use tabs for indentation
  -v, --version          Print version information
  -x, --xpath string     Extract the node(s) from XML
`

type options struct {
	attr     string
	color    bool
	compact  bool
	depth    int
	extract  string
	html     bool
	inPlace  bool
	indent   int
	json     bool
	noColor  bool
	node     bool
	query    string
	tab      bool
	xpath    string
	files    []string
}

func fail(msg string) {
	fmt.Fprintln(os.Stderr, "Error: "+msg)
	os.Exit(1)
}

func parseArgs(argv []string) *options {
	o := &options{indent: 2, depth: -1}
	i := 0
	for i < len(argv) {
		a := argv[i]
		if a == "--" {
			i++
			o.files = append(o.files, argv[i:]...)
			break
		}
		if strings.HasPrefix(a, "--") {
			name := a[2:]
			var val string
			var hasVal bool
			if k := strings.IndexByte(name, '='); k >= 0 {
				val, hasVal = name[k+1:], true
				name = name[:k]
			}
			switch name {
			case "attr", "extract", "query", "xpath":
				if !hasVal {
					i++
					if i >= len(argv) {
						fail("flag needs an argument: --" + name)
					}
					val = argv[i]
				}
				switch name {
				case "attr":
					o.attr = val
				case "extract":
					o.extract = val
				case "query":
					o.query = val
				case "xpath":
					o.xpath = val
				}
			case "indent", "depth":
				if !hasVal {
					i++
					if i >= len(argv) {
						fail("flag needs an argument: --" + name)
					}
					val = argv[i]
				}
				var n int
				if _, err := fmt.Sscanf(val, "%d", &n); err != nil {
					fail("invalid argument \"" + val + "\" for \"--" + name + "\" flag: strconv.ParseInt: parsing \"" + val + "\": invalid syntax")
				}
				if name == "indent" {
					o.indent = n
				} else {
					o.depth = n
				}
			case "color":
				o.color = true
			case "no-color":
				o.noColor = true
			case "html":
				o.html = true
			case "in-place":
				o.inPlace = true
			case "json":
				o.json = true
			case "node":
				o.node = true
			case "tab":
				o.tab = true
			case "compact":
				o.compact = true
			case "help":
				fmt.Print(helpText)
				os.Exit(0)
			case "version":
				fmt.Println(version)
				os.Exit(0)
			default:
				fail("unknown flag: --" + name)
			}
			i++
			continue
		}
		if strings.HasPrefix(a, "-") && len(a) > 1 {
			short := a[1:]
			for len(short) > 0 {
				c := short[0]
				switch c {
				case 'a':
					o.attr = argVal(&i, argv, short[1:])
					short = ""
					continue
				case 'e':
					o.extract = argVal(&i, argv, short[1:])
					short = ""
					continue
				case 'q':
					o.query = argVal(&i, argv, short[1:])
					short = ""
					continue
				case 'x':
					o.xpath = argVal(&i, argv, short[1:])
					short = ""
					continue
				case 'd':
					s := argVal(&i, argv, short[1:])
					var n int
					if _, err := fmt.Sscanf(s, "%d", &n); err != nil {
						fail("invalid argument \"" + s + "\" for \"-d, --depth\" flag: strconv.ParseInt: parsing \"" + s + "\": invalid syntax")
					}
					o.depth = n
					short = ""
					continue
				case 'c':
					o.color = true
				case 'm':
					o.html = true
				case 'i':
					o.inPlace = true
				case 'j':
					o.json = true
				case 'n':
					o.node = true
				case 'h':
					fmt.Print(helpText)
					os.Exit(0)
				case 'v':
					fmt.Println(version)
					os.Exit(0)
				default:
					fail("unknown shorthand flag: '" + string(c) + "' in -" + short)
				}
				short = short[1:]
			}
			i++
			continue
		}
		o.files = append(o.files, a)
		i++
	}
	return o
}

func argVal(i *int, argv []string, rest string) string {
	if rest != "" {
		return rest
	}
	*i++
	if *i >= len(argv) {
		fail("flag needs an argument")
	}
	return argv[*i]
}

func main() {
	o := parseArgs(os.Args[1:])

	if o.attr != "" && o.query == "" {
		fail("query option (-q) is missed for attribute selection")
	}
	if o.inPlace {
		if len(o.files) != 1 {
			fail("in-place formatting requires a file path (and only one file path)")
		}
	}

	var data []byte
	if len(o.files) > 0 {
		for _, f := range o.files {
			b, err := os.ReadFile(f)
			if err != nil {
				fail(err.Error())
			}
			data = append(data, b...)
			if o.inPlace {
				process(o, b, f)
			}
		}
		if o.inPlace {
			return
		}
	} else {
		b, err := io.ReadAll(os.Stdin)
		if err != nil {
			fail(err.Error())
		}
		data = b
	}
	out := process(o, data, "")
	fmt.Print(out)
}

func process(o *options, data []byte, file string) string {
	if len(data) == 0 {
		fmt.Print(helpText)
		os.Exit(0)
	}
	// strip leading whitespace for detection
	trimmed := strings.TrimLeft(string(data), " \t\r\n")
	ct := detectType(trimmed)
	switch ct {
	case "json":
		return prettyJSON(string(data), o.compact)
	case "xml", "html":
		doc, err := internal.Parse([]byte(trimmed), o.html)
		if err != nil {
			fail(err.Error())
		}
		if o.attr != "" && o.query != "" {
			nodes := internal.CSSMatch(doc, o.query)
			var sb strings.Builder
			for _, n := range nodes {
				for _, a := range n.Attrs {
					if a.Name == o.attr {
						sb.WriteString(a.Value)
					}
				}
				sb.WriteString("\n")
			}
			return sb.String()
		}
		var nodes []*Node
		if o.xpath != "" {
			nodes, err = internal.XPathMatch(doc, o.xpath)
			if err != nil {
				fail(err.Error())
			}
		} else if o.extract != "" {
			all, err := internal.XPathMatch(doc, o.extract)
			if err != nil {
				fail(err.Error())
			}
			if len(all) > 0 {
				nodes = all[:1]
			}
		} else if o.query != "" {
			nodes = internal.CSSMatch(doc, o.query)
		}
		if nodes != nil {
			if o.node {
				var sb strings.Builder
				for _, n := range nodes {
					w := &Node{Kind: ndElement, Name: n.Name, Attrs: n.Attrs, Kids: n.Kids}
					sub := &Document{Kids: []*Node{w}, HTML: o.html}
					opts := &internal.Options{IndentUnit: unit(o), HTML: o.html}
					sb.WriteString(internal.Format(sub, opts))
				}
				return sb.String()
			}
			var sb strings.Builder
			for _, n := range nodes {
				sb.WriteString(strings.TrimSpace(internal.TextContent(n)) + "\n")
			}
			return sb.String()
		}
		if o.json {
			root := firstElement(doc)
			if root == nil {
				return ""
			}
			v := internal.JSONTree(root, 0, o.depth)
			internal.SortJSON(v)
			var sb strings.Builder
			internal.WriteJSON(v, "", o.compact, &sb)
			sb.WriteString("\n")
			return sb.String()
		}
		opts := &internal.Options{IndentUnit: unit(o), HTML: o.html}
		sub := &Document{Kids: doc.Kids, HTML: o.html}
		return internal.Format(sub, opts)
	default:
		// plain text: format as text
		doc, err := internal.Parse(data, false)
		if err != nil {
			fail(err.Error())
		}
		opts := &internal.Options{IndentUnit: unit(o)}
		sub := &Document{Kids: doc.Kids}
		return internal.Format(sub, opts)
	}
}

func unit(o *options) string {
	if o.tab {
		return "\t"
	}
	return strings.Repeat(" ", o.indent)
}

func firstElement(doc *Document) *Node {
	for i := len(doc.Kids) - 1; i >= 0; i-- {
		if doc.Kids[i].Kind == ndElement {
			return doc.Kids[i]
		}
	}
	return nil
}

func detectType(s string) string {
	if s == "" {
		return "unknown"
	}
	switch s[0] {
	case '<':
		return "xml"
	case '{', '[':
		return "json"
	}
	return "text"
}

func prettyJSON(s string, compact bool) string {
	dec := json.NewDecoder(strings.NewReader(s))
	var sb strings.Builder
	first := true
	for {
		var raw json.RawMessage
		if err := dec.Decode(&raw); err != nil {
			break
		}
		if !first {
			sb.WriteString(",")
		}
		first = false
		var v interface{}
		_ = json.Unmarshal(raw, &v)
		sb.WriteString(formatJSONValue(v, "", compact))
	}
	sb.WriteString("\n")
	return sb.String()
}

func formatJSONValue(v interface{}, indent string, compact bool) string {
	switch t := v.(type) {
	case map[string]interface{}:
		if len(t) == 0 {
			if compact {
				return "{}"
			}
			return "{\n\n" + indent + "}"
		}
		keys := make([]string, 0, len(t))
		for k := range t {
			keys = append(keys, k)
		}
		for i := 0; i < len(keys); i++ {
			for j := i + 1; j < len(keys); j++ {
				if keys[j] < keys[i] {
					keys[i], keys[j] = keys[j], keys[i]
				}
			}
		}
		var sb strings.Builder
		sb.WriteString("{")
		for i, k := range keys {
			if compact {
				if i > 0 {
					sb.WriteString(",")
				}
			} else {
				sb.WriteString("\n" + indent + "  ")
			}
			sb.WriteString(strconvQuote(k) + ": ")
			sb.WriteString(formatJSONValue(t[k], indent+"  ", compact))
			if !compact {
				if i < len(keys)-1 {
					sb.WriteString(",")
				}
			}
		}
		if compact {
			sb.WriteString("}")
		} else {
			sb.WriteString("\n" + indent + "}")
		}
		return sb.String()
	case []interface{}:
		if len(t) == 0 {
			if compact {
				return "[]"
			}
			return "[\n\n" + indent + "]"
		}
		var sb strings.Builder
		sb.WriteString("[")
		for i, c := range t {
			if compact {
				if i > 0 {
					sb.WriteString(",")
				}
			} else {
				sb.WriteString("\n" + indent + "  ")
			}
			sb.WriteString(formatJSONValue(c, indent+"  ", compact))
			if !compact {
				if i < len(t)-1 {
					sb.WriteString(",")
				}
			}
		}
		if compact {
			sb.WriteString("]")
		} else {
			sb.WriteString("\n" + indent + "]")
		}
		return sb.String()
	case string:
		return strconvQuote(t)
	case float64:
		return fmt.Sprintf("%v", t)
	case bool:
		if t {
			return "true"
		}
		return "false"
	case nil:
		return "null"
	}
	return ""
}

func strconvQuote(s string) string { return strconvQuote(s) }
func strconvQuote(s string) string {
	var sb strings.Builder
	sb.WriteByte('"')
	for _, c := range s {
		switch c {
		case '"':
			sb.WriteString("\\\"")
		case '\\':
			sb.WriteString("\\\\")
		case '\n':
			sb.WriteString("\\n")
		case '\t':
			sb.WriteString("\\t")
		case '\r':
			sb.WriteString("\\r")
		default:
			if c < 0x20 {
				sb.WriteString(fmt.Sprintf("\\x%02x", c))
			} else {
				sb.WriteRune(c)
			}
		}
	}
	sb.WriteByte('"')
	return sb.String()
}
